-- The Carbide insert code key on the Grades (Carbide) tab (editable there); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.carbide', $ck${"title": "Code key for carbide inserts – ISO 1832", "example": "WNMG 080408 E-GN", "sections": [{"title": "1 · Shape", "sample": "W", "rows": [{"code": "R", "meaning": "Round"}, {"code": "S", "meaning": "Square, 90°"}, {"code": "T", "meaning": "Triangle, 60°"}, {"code": "C", "meaning": "Rhombic, 80° / 100°"}, {"code": "E", "meaning": "Rhombic, 75°"}, {"code": "D", "meaning": "Rhombic, 55°"}, {"code": "V", "meaning": "Rhombic, 35°"}, {"code": "Y", "meaning": "Rhombic, 25°"}, {"code": "W", "meaning": "Trigon, 80°"}, {"code": "L", "meaning": "Rectangle"}, {"code": "K", "meaning": "Parallelogram, 55°"}, {"code": "Q", "meaning": "Special, 80°"}]}, {"title": "2 · Clearance angle", "sample": "N", "rows": [{"code": "N", "meaning": "0°"}, {"code": "B", "meaning": "5°"}, {"code": "C", "meaning": "7°"}, {"code": "P", "meaning": "11°"}, {"code": "O", "meaning": "Other"}]}, {"title": "3 · Tolerance", "sample": "M", "rows": [{"code": "E", "meaning": "m ±0.025 · s ±0.025 · IC ±0.025"}, {"code": "G", "meaning": "m ±0.025 · s ±0.13 · IC ±0.025"}, {"code": "M", "meaning": "m ±0.08–0.18 · s ±0.13 · IC ±0.05–0.13"}, {"code": "U", "meaning": "m ±0.13–0.38 · s ±0.13 · IC ±0.08–0.25"}], "note": "mm. For M and U the exact tolerance depends on the insert size (see the tolerance table below)."}, {"title": "4 · Type", "sample": "G", "rows": [{"code": "A", "meaning": "Without chipbreaker, with hole"}, {"code": "G", "meaning": "Chipbreaker on both sides, with hole"}, {"code": "M", "meaning": "Chipbreaker on one side, with hole"}, {"code": "S", "meaning": "Chipbreaker on one side, with hole"}, {"code": "R", "meaning": "Chipbreaker on one side, without hole"}, {"code": "B", "meaning": "Countersink on one side, with hole"}, {"code": "W", "meaning": "Countersink on one side, with hole"}, {"code": "T", "meaning": "Chipbreaker on one side, with hole and countersink"}, {"code": "H", "meaning": "Chipbreaker on one side, with hole and countersink"}, {"code": "P", "meaning": "Neg. / pos. on one or both sides, with hole"}, {"code": "Z", "meaning": "Special"}, {"code": "X", "meaning": "Special"}]}, {"title": "5 · Cutting edge length", "sample": "08", "rows": [{"code": "##", "meaning": "Cutting edge length L in mm (by shape and IC — see the table below)"}]}, {"title": "6 · Thickness", "sample": "04", "rows": [{"code": "01", "meaning": "1.59 mm"}, {"code": "T1", "meaning": "1.98 mm"}, {"code": "02", "meaning": "2.38 mm"}, {"code": "03", "meaning": "3.18 mm"}, {"code": "T3", "meaning": "3.97 mm"}, {"code": "04", "meaning": "4.76 mm"}, {"code": "06", "meaning": "6.35 mm"}, {"code": "07", "meaning": "7.94 mm"}]}, {"title": "7 · Corner radius", "sample": "08", "rows": [{"code": "02", "meaning": "0.2 mm"}, {"code": "04", "meaning": "0.4 mm"}, {"code": "08", "meaning": "0.8 mm"}, {"code": "12", "meaning": "1.2 mm"}, {"code": "16", "meaning": "1.6 mm"}, {"code": "20", "meaning": "2.0 mm"}, {"code": "24", "meaning": "2.4 mm"}]}, {"title": "8 · Cutting edge (optional)", "sample": "E", "rows": [{"code": "F", "meaning": "Sharp"}, {"code": "E", "meaning": "Honed (rounded)"}, {"code": "T", "meaning": "Chamfered (negative land)"}, {"code": "S", "meaning": "Chamfered + honed"}]}, {"title": "9 · Chipformer", "sample": "GN", "rows": [{"code": "SF", "meaning": "Chipformer"}, {"code": "AS/AF", "meaning": "Chipformer"}, {"code": "TF", "meaning": "Chipformer"}, {"code": "NM", "meaning": "Chipformer"}, {"code": "PF", "meaning": "Chipformer"}, {"code": "../Z-RF/LF", "meaning": "Chipformer"}, {"code": "PP", "meaning": "Chipformer"}, {"code": "TNM", "meaning": "Chipformer"}, {"code": "NF", "meaning": "Chipformer"}, {"code": "WF", "meaning": "Chipformer"}, {"code": "GN", "meaning": "Chipformer"}, {"code": "NR", "meaning": "Chipformer"}, {"code": "SM", "meaning": "Chipformer"}, {"code": "WG", "meaning": "Chipformer"}, {"code": "NMS", "meaning": "Chipformer"}, {"code": "RP", "meaning": "Chipformer"}, {"code": "14", "meaning": "Chipformer"}, {"code": "VL", "meaning": "Chipformer"}], "note": "R / L in a chipformer name (e.g. ..-RF / LF): right-hand / left-hand insert."}], "tables": [{"title": "Tolerance classes M and U by IC (mm)", "groups": [{"label": "", "span": 1}, {"label": "Tolerance on m", "span": 2}, {"label": "Tolerance on IC", "span": 2}], "columns": ["IC", "Class M", "Class U", "Class M", "Class U"], "rows": [["6.35", "±0.08", "±0.13", "±0.05", "±0.08"], ["9.52", "±0.08", "±0.13", "±0.05", "±0.08"], ["12.70", "±0.13", "±0.20", "±0.08", "±0.13"], ["15.87", "±0.15", "±0.27", "±0.10", "±0.18"], ["19.05", "±0.15", "±0.27", "±0.10", "±0.18"], ["25.40", "±0.18", "±0.38", "±0.13", "±0.25"]]}, {"title": "Cutting edge length L by shape and IC", "groups": [{"label": "IC", "span": 2}, {"label": "Symbol (L)", "span": 8}], "columns": ["IC (inch)", "IC (mm)", "C", "D", "R", "S", "T", "V", "W", "Q"], "rows": [["5/32", "3.97", "", "04", "", "03", "06", "06", "02 (WBMT 06…)", ""], ["7/32", "5.56", "05", "", "", "", "09", "", "", ""], ["1/4", "6.35", "06", "07", "", "", "11", "11", "", ""], ["9/32", "7.15", "", "", "", "", "", "12", "", ""], ["", "8.00", "", "", "08", "", "", "", "", ""], ["3/8", "9.52", "09", "11", "", "09", "16", "16", "06", "09"], ["", "10.00", "", "", "10", "", "", "", "", ""], ["", "12.00", "", "", "12", "", "", "", "", ""], ["1/2", "12.70", "12", "15", "", "12", "22", "22", "08", "12"], ["5/8", "15.88", "16", "", "", "15", "27", "", "", ""], ["", "16.00", "", "", "16", "", "", "", "", ""], ["3/4", "19.05", "19", "", "", "19", "33", "", "13", ""], ["", "20.00", "", "", "20", "", "", "", "", ""], ["", "25.00", "", "", "25", "", "", "", "", ""], ["1", "25.40", "", "", "", "25", "", "", "", ""]]}]}$ck$)
